-- Initial catalog (AC, AC fara unitate exterioara, recuperatoare, ventilatoare baie, dezumidificatoare).
-- Prices are RON as imported; review in /admin. Stock is a placeholder.
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, sku = EXCLUDED.sku, brand = EXCLUDED.brand, category = EXCLUDED.category,
  description = EXCLUDED.description, image_url = EXCLUDED.image_url, gallery = EXCLUDED.gallery,
  features = EXCLUDED.features, specs = EXCLUDED.specs;
