  ('Aer condiționat Heiko Rosa Black 9000 BTU', 'aer-conditionat-heiko-rosa-black-9000-btu', 'Y1000', 'Heiko', 'Aer Condiționat', 'Rosa Black îmbină designul negru elegant cu tehnologia inverter. Are Wi-Fi inclus, funcții SMART airflow și Self Clean, eficiență energetică ridicată și funcționare silențioasă, pentru confort în orice anotimp.', 2676.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/20700-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/20700-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/20700-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/20700-3.webp']::text[], '["Design negru", "Wi-Fi inclus", "SMART airflow", "Self Clean", "Funcționare silențioasă", "9000 BTU"]'::jsonb, '{"Capacitate": "9000 BTU"}'::jsonb, 10),
