  ('Aer condiționat tip consolă Heiko C-Console 11000 BTU', 'aer-conditionat-heiko-c-console-11000-btu', 'Y1015', 'Heiko', 'Aer Condiționat', 'Aparat tip consolă, cu clasă energetică A++, tehnologie inverter și SMART airflow. Este util mai ales acolo unde montajul pe perete sau pe tavan este limitat: apartamente, birouri și spații comerciale. Răcește rapid, încălzește stabil și consumă puțin.', 5136.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-3.webp']::text[], '["Tip consolă", "Clasă energetică A++", "Tehnologie inverter", "SMART airflow", "Funcționare silențioasă", "11000 BTU"]'::jsonb, '{"Capacitate": "11000 BTU"}'::jsonb, 10),
  ('Aer condiționat tip consolă Heiko C-Console 17000 BTU', 'aer-conditionat-heiko-c-console-17000-btu', 'Y1016', 'Heiko', 'Aer Condiționat', 'Aparat tip consolă, cu clasă energetică A++, tehnologie inverter și SMART airflow. Este util mai ales acolo unde montajul pe perete sau pe tavan este limitat: apartamente, birouri și spații comerciale. Răcește rapid, încălzește stabil și consumă puțin.', 6342.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/21339-3.webp']::text[], '["Tip consolă", "Clasă energetică A++", "Tehnologie inverter", "SMART airflow", "Funcționare silențioasă", "17000 BTU"]'::jsonb, '{"Capacitate": "17000 BTU"}'::jsonb, 10),
  ('Aer condiționat fără unitate exterioară Ceiling 12000 BTU', 'aer-conditionat-fara-unitate-exterioara-ceiling-12000-btu', 'X1039', NULL, 'Aer Condiționat fără Unitate Exterioară', 'Aparat fără unitate exterioară, cu montaj orizontal pe tavan și înălțime de doar 25,5 cm. Folosește agent frigorific R32, compresor DC Inverter și face atât răcire, cât și încălzire. Este soluția pentru locuințele în care montajul clasic, pe perete, nu este posibil. Există și versiune ELEC, cu încălzitor electric.', 23882.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4210-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4210-1.webp']::text[], '["12000 BTU", "Montaj pe tavan, înălțime 25,5 cm", "Agent frigorific R32", "Compresor DC Inverter", "Răcire și încălzire"]'::jsonb, '{"Tip montaj": "Tavan", "Putere": "12000 BTU", "Agent frigorific": "R32", "Tip compresor": "DC Inverter", "Funcție": "Racire + Incalzire", "Control inteligent": "WiFi"}'::jsonb, 10),
  ('Aer condiționat fără unitate exterioară Mini 9000 BTU', 'aer-conditionat-fara-unitate-exterioara-mini-9000-btu', 'X1040', NULL, 'Aer Condiționat fără Unitate Exterioară', 'Aparat compact fără unitate exterioară, de 9000 BTU, ideal când nu poți monta o unitate pe fațadă. Folosește agent frigorific R290 (propan), compresor DC Inverter, face răcire și încălzire și se controlează din aplicația de pe telefon.', 16684.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4056-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4056-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4056-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4056-3.webp']::text[], '["9000 BTU", "Agent frigorific R290", "Compresor DC Inverter", "Răcire și încălzire", "Control din aplicație"]'::jsonb, '{"Tip montaj": "Orizontal", "Putere": "9000 BTU", "Agent frigorific": "R290", "Tip compresor": "DC Inverter", "Funcție": "Racire + Incalzire", "Control inteligent": "WiFi"}'::jsonb, 10),
  ('Aer condiționat fără unitate exterioară Dual Power 10000 BTU', 'aer-conditionat-fara-unitate-exterioara-dual-power-10000-btu', 'X1036', NULL, 'Aer Condiționat fără Unitate Exterioară', 'Aparat fără unitate exterioară din gama Dual Power, de 10000 BTU, cu agent frigorific R32 și compresor DC Inverter. Răcește și încălzește, iar controlul se face din aplicația de pe telefon. Un design subțire, care se integrează discret în locuință.', 16684.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4057-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4057-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4057-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4057-3.webp']::text[], '["10000 BTU", "Agent frigorific R32", "Compresor DC Inverter", "Răcire și încălzire", "Control din aplicație"]'::jsonb, '{"Tip montaj": "Orizontal", "Putere": "10000 BTU", "Agent frigorific": "R32", "Tip compresor": "DC Inverter", "Funcție": "Racire + Incalzire", "Control inteligent": "WiFi"}'::jsonb, 10),
  ('Aer condiționat fără unitate exterioară 12000 BTU', 'aer-conditionat-fara-unitate-exterioara-12000-btu', 'X1037', NULL, 'Aer Condiționat fără Unitate Exterioară', 'Aparat fără unitate exterioară, de 12000 BTU, cu design subțire și discret, care se potrivește în locuințe în care o unitate pe fațadă nu este acceptată. Folosește R32, compresor DC Inverter și face răcire și încălzire.', 17994.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4208-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4208-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4208-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4208-3.webp']::text[], '["12000 BTU", "Agent frigorific R32", "Compresor DC Inverter", "Răcire și încălzire", "Design subțire"]'::jsonb, '{"Tip montaj": "Orizontal", "Putere": "12000 BTU", "Agent frigorific": "R32", "Tip compresor": "DC Inverter", "Funcție": "Racire + Incalzire", "Control inteligent": "WiFi"}'::jsonb, 10),
  ('Aer condiționat fără unitate exterioară 12000 BTU ELEC 2 kW', 'aer-conditionat-fara-unitate-exterioara-12000-btu-elec', 'X1038', NULL, 'Aer Condiționat fără Unitate Exterioară', 'Varianta ELEC a aparatului fără unitate exterioară de 12000 BTU: pompa de căldură este completată de un încălzitor electric de 1800 W, care intervine automat la temperaturi foarte scăzute sau pentru a încălzi rapid o cameră rece. Poate oferi peste 2 kW încălzire chiar și la -7 °C.', 19302.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4209-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4209-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4209-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4209-3.webp']::text[], '["12000 BTU", "Încălzitor electric 1800 W", "Peste 2 kW încălzire la -7 °C", "Agent frigorific R32", "Compresor DC Inverter"]'::jsonb, '{"Tip montaj": "Orizontal", "Putere": "12000 BTU", "Agent frigorific": "R32", "Tip compresor": "DC Inverter", "Funcție": "Racire + Incalzire", "Control inteligent": "WiFi"}'::jsonb, 10),
  ('Recuperator de căldură SEVi160 PRO', 'recuperator-caldura-sevi160-pro', 'S1000', 'SEVentilation', 'Recuperatoare de Căldură', 'Sistem complet echipat de ventilație descentralizată cu recuperare de căldură, pentru montaj în perete (tubulatură de 480 mm, diametru 160 mm), cu panou de control integrat. Aduce aer proaspăt și limitează pierderile de căldură și umezeala din locuință.', 3748.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3836-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3836-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3836-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3836-3.webp']::text[], '["Diametru 160 mm, lungime 480 mm", "Debit 60 m³/h", "Panou de control integrat"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Recuperator de căldură SEVi160 PRO RC wireless', 'recuperator-caldura-sevi160-pro-rc-wireless', 'S1018', 'SEVentilation', 'Recuperatoare de Căldură', 'Versiune wireless a sistemului SEVi160 PRO (480 mm, diametru 160 mm): unitățile comunică radio, fără cabluri între ele, ceea ce simplifică instalarea, mai ales la renovări. Telecomanda nu este inclusă.', 4812.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3929-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3929-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3929-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3929-3.webp']::text[], '["Control wireless (RF)", "Fără cabluri între unități", "Debit 60 m³/h", "Telecomandă neinclusă"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Wireless / RF", "Telecomandă inclusă": "nu"}'::jsonb, 10),
  ('Recuperator de căldură NovingAIR Phantom EVO APP 160', 'recuperator-caldura-novingair-phantom-evo-app-160', 'E1001', 'NovingAIR', 'Recuperatoare de Căldură', 'Recuperator de căldură descentralizat care se controlează prin aplicația NVG.app, de oriunde. Asigură ventilație mecanică adecvată în locuințe și spații de birouri, fără tubulaturi lungi. Telecomanda nu este inclusă.', 3038.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4206-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4206-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4206-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4206-3.webp']::text[], '["Diametru 160 mm", "Debit 90 m³/h", "Control din aplicația NVG.app"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Aplicatie telefon", "Telecomandă inclusă": "nu"}'::jsonb, 10),
  ('Recuperator de căldură NovingAIR Primo Active 160', 'recuperator-caldura-novingair-primo-active-160', 'E1008', 'NovingAIR', 'Recuperatoare de Căldură', 'Recuperator descentralizat cu schimbător ceramic, cu randament de până la 93%. Schimbătorul ceramic nu absoarbe apă, ceea ce ajută la igiena aerului. O singură telecomandă (neinclusă) este suficientă pentru mai multe unități conectate între ele.', 1132.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4122-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4122-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4122-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4122-3.webp']::text[], '["Randament recuperare până la 93%", "Schimbător ceramic", "Debit 90 m³/h", "Diametru 160 mm"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Telecomandă", "Telecomandă inclusă": "nu"}'::jsonb, 10),
  ('Recuperator de căldură NovingAIR Phantom EVO Active 160', 'recuperator-caldura-novingair-phantom-evo-active-160', 'E1000', 'NovingAIR', 'Recuperatoare de Căldură', 'Sistem de ventilație descentralizată cu recuperare de căldură, pentru locuințe unde nu se poate monta un sistem centralizat cu tubulaturi. Oferă aer proaspăt continuu, controlul umidității și evacuarea aerului viciat, fără pierderile de căldură ale aerisirii obișnuite.', 2080.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3921-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3921-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3921-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3921-3.webp']::text[], '["Diametru 160 mm", "Debit 90 m³/h", "Control cu telecomandă (neinclusă)"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Telecomandă", "Telecomandă inclusă": "nu"}'::jsonb, 10),
  ('Recuperator de căldură NovingAIR Phantom Wireless 160', 'recuperator-caldura-novingair-phantom-wireless-160', 'E1005', 'NovingAIR', 'Recuperatoare de Căldură', 'Unul dintre cele mai silențioase recuperatoare descentralizate, cu zgomot de la doar 4 dB. Unitățile comunică wireless, deci nu sunt necesare cabluri între ele, iar senzorii de umiditate și lumină reglează automat funcționarea. Randament de recuperare de până la 93%, potrivit pentru renovări.', 2677.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3923-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3923-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3923-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3923-3.webp']::text[], '["Zgomot de la 4 dB", "Control wireless", "Randament până la 93%", "Senzori de umiditate și lumină", "Debit 90 m³/h"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Wireless / RF", "Telecomandă inclusă": "nu"}'::jsonb, 10),
  ('Unitate de ventilație cu recuperare NovingAIR Power 200', 'unitate-ventilatie-recuperare-novingair-power-200', 'E1002', 'NovingAIR', 'Recuperatoare de Căldură', 'Unitate de ventilație descentralizată cu recuperare de căldură și flux alternant, pentru locuințe și spații de business. Include tubulatură standard de 200 mm, pentru pereți de maximum 500 mm grosime; pentru pereți mai groși alegem împreună tubulatura potrivită.', 2874.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4205-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4205-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4205-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4205-3.webp']::text[], '["Diametru 200 mm", "Debit 140 m³/h", "Include tubulatură standard (perete până la 500 mm)", "Flux alternant"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "200 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Recuperator de căldură SEVi160 DUO', 'recuperator-caldura-sevi160-duo', 'S1008', 'SEVentilation', 'Recuperatoare de Căldură', 'Unitate de ventilație cu recuperare de căldură din familia SEVi160, de 480 mm, cu control wireless, pentru montaj în perete.', 7139.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3837-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3837-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3837-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3837-3.webp']::text[], '["Diametru 160 mm, lungime 480 mm", "Control wireless (RF)"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Wireless / RF", "Telecomandă inclusă": "nu"}'::jsonb, 10),
  ('Recuperator de căldură SEVi160 CA Clean Air', 'recuperator-caldura-sevi160-ca-clean-air', 'S1033', 'SEVentilation', 'Recuperatoare de Căldură', 'Varianta Clean Air a sistemului SEVi160, cu filtru F7 pentru aer foarte curat, util în special pentru persoanele cu alergii. Unitate cu recuperare de căldură de 480 mm, cu panou de control integrat.', 3946.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3866-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3866-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3866-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3866-3.webp']::text[], '["Filtru F7", "Diametru 160 mm, lungime 480 mm", "Panou de control integrat"]'::jsonb, '{"Tip produs": "Recuperator caldura", "Diametru": "160 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Unitate de ventilație A160 fără recuperare de căldură', 'unitate-ventilatie-a160-fara-recuperare', 'S1079', 'SEVentilation', 'Ventilatoare Baie', 'Sistem complet echipat de ventilație pentru băi și camere umede, fără recuperare de căldură, cu diametru de 160 mm și panou de control integrat.', 1972.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3863-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3863-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3863-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3863-3.webp']::text[], '["Diametru 160 mm", "Fără recuperare de căldură", "Panou de control integrat"]'::jsonb, '{"Tip produs": "Ventilator baie", "Diametru": "160 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Ventilator de baie Aviant cu senzori de umiditate și miros', 'ventilator-baie-aviant-senzor-umiditate-miros', 'O1000', 'Aviant', 'Ventilatoare Baie', 'Ventilator de baie foarte silențios, cu senzori de lumină, umiditate și calitate a aerului (miros), configurabil din aplicația de pe telefon. Nu se conectează la întrerupătorul luminii din baie, ci are nevoie de alimentare permanentă.', 1250.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3913-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3913-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3913-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3913-3.webp']::text[], '["Diametru 100 mm", "Senzori de lumină, umiditate și miros", "Control din aplicație", "Alimentare permanentă"]'::jsonb, '{"Tip produs": "Ventilator baie", "Diametru": "100 mm", "Control": "Aplicatie telefon, Panou integrat"}'::jsonb, 10),
  ('Ventilator de baie silențios Pulsar', 'ventilator-baie-silentios-pulsar', 'O1001', 'NovingAIR', 'Ventilatoare Baie', 'Ventilator modern pentru eliminarea rapidă a umezelii și a mirosurilor, cu senzori de umiditate și de lumină și control prin aplicație. Se montează pe perete sau în tavan și funcționează la doar 17–20 dB(A), aproape imperceptibil. Debit de până la 110 m³/h.', 1067.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/18489-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/18489-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/18489-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/18489-3.webp']::text[], '["Zgomot 17–20 dB(A)", "Debit până la 110 m³/h", "Senzori de umiditate și lumină", "Control din aplicație"]'::jsonb, '{}'::jsonb, 10),
  ('Ventilator de baie A100 FS NL', 'ventilator-baie-a100-fs-nl', 'S1082', 'SEVentilation', 'Ventilatoare Baie', 'Ventilator A100 pentru camere cu umiditate ridicată: băi, bucătării, camere tehnice, uscătorii. Modelul NL se comandă dintr-un comutator extern (de exemplu odată cu lumina) și are timer reglabil între 2 și 45 de minute.', 1003.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3881-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3881-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3881-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3881-3.webp']::text[], '["Diametru 100 mm", "Comutator extern", "Timer reglabil 2–45 min"]'::jsonb, '{"Tip produs": "Ventilator baie", "Diametru": "100 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Ventilator de baie A100 FS PR cu senzor de prezență', 'ventilator-baie-a100-fs-pr-senzor-prezenta', 'S1084', 'SEVentilation', 'Ventilatoare Baie', 'Ventilator A100 cu senzor de prezență în infraroșu și timer de întârziere, pentru băi și alte camere umede. Ventilează eficient până la 67 m³/h, cu debit conform normativului german.', 1549.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3882-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3882-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3882-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3882-3.webp']::text[], '["Diametru 100 mm", "Senzor de prezență în infraroșu", "Debit până la 67 m³/h", "Timer de întârziere"]'::jsonb, '{"Tip produs": "Ventilator baie", "Diametru": "100 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Ventilator de baie A100 FS HTM', 'ventilator-baie-a100-fs-htm', 'S1083', 'SEVentilation', 'Ventilatoare Baie', 'Ventilator A100 pentru băi, bucătării și alte camere cu umiditate ridicată. Ventilează eficient până la 67 m³/h, cu debit conform normativului german.', 1161.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3880-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3880-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3880-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3880-3.webp']::text[], '["Diametru 100 mm", "Debit până la 67 m³/h"]'::jsonb, '{"Tip produs": "Ventilator baie", "Diametru": "100 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Ventilator centrifugal SEVentilation A80i-FS-S', 'ventilator-centrifugal-seventilation-a80i-fs-s', 'S1080', 'SEVentilation', 'Ventilatoare Baie', 'Ventilator centrifugal silențios și eficient energetic, cu grilă interioară de design și capac cu filtru, cu indicator pentru schimbarea filtrului. Debit de la 0 la 90 m³/h, cu ventilație de bază și la cerere și întârziere la pornire reglabilă. Se montează în carcase îngropate sau aparente (carcasele se cumpără separat).', 1522.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4126-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4126-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4126-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4126-3.webp']::text[], '["Diametru 80 mm", "Debit 0–90 m³/h", "Filtru cu indicator de schimbare", "Carcasă vândută separat"]'::jsonb, '{"Tip produs": "Ventilatie bucãtãrie, Ventilator baie", "Diametru": "80 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Ventilator centrifugal SEVentilation A80i-FS-K cu senzor de umiditate', 'ventilator-centrifugal-seventilation-a80i-fs-k-senzor-umiditate', 'S1081', 'SEVentilation', 'Ventilatoare Baie', 'Versiunea cu senzor de umiditate a ventilatorului A80i: silențios, eficient energetic, cu panou interior de design, filtru și indicator de schimbare a filtrului. Debit de la 0 la 90 m³/h, ventilație de bază și la cerere. Se montează în carcase îngropate sau aparente (vândute separat).', 2215.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4204-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4204-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4204-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4204-3.webp']::text[], '["Diametru 80 mm", "Senzor de umiditate", "Debit 0–90 m³/h", "Carcasă vândută separat"]'::jsonb, '{"Tip produs": "Ventilatie bucãtãrie, Ventilator baie", "Diametru": "80 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Valvă de introducere aer termoreglabilă RTP100', 'valva-introducere-aer-termoreglabila-rtp100', 'O1007', NULL, 'Ventilatoare Baie', 'Valvă de admisie a aerului proaspăt cu autoreglare termică: ajustează automat deschiderea în funcție de condițiile meteo, ca să intre aer proaspăt fără să se piardă inutil căldura din locuință.', 395.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3906-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3906-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3906-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3906-3.webp']::text[], '["Diametru 100 mm", "Autoreglare termică"]'::jsonb, '{"Tip produs": "Ventila?ie fãrã recuperare", "Diametru": "100 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Valvă de ventilație RMP 100', 'valva-ventilatie-rmp-100', 'O1008', NULL, 'Ventilatoare Baie', 'Valvă pentru aport de aer proaspăt, cu filtru de praf și reglaj manual. Poate compensa aerul extras de hota de bucătărie sau poate completa un ventilator de extracție într-un sistem de ventilație fără recuperare de căldură.', 274.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3907-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3907-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3907-2.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3907-3.webp']::text[], '["Diametru 100 mm", "Filtru de praf", "Reglaj manual"]'::jsonb, '{"Tip produs": "Ventila?ie fãrã recuperare", "Diametru": "100 mm", "Control": "Panou integrat"}'::jsonb, 10),
  ('Ventilator de baie centrifugal Aerauliqa QX100', 'ventilator-baie-centrifugal-aerauliqa-qx100', 'A1028', 'Aerauliqa', 'Ventilatoare Baie', 'Ventilator centrifugal pentru extragerea aerului din spații mici și medii, cu filtru antipraf. Se montează pe perete sau tavan, la suprafață sau încastrat în gips-carton. Structură din ABS și polistiren.', 603.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4106-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4106-1.webp']::text[], '["Diametru 100 mm", "Filtru antipraf", "Montaj aparent sau încastrat"]'::jsonb, '{}'::jsonb, 10),
  ('Controler A80-NS pentru ventilatoare A80', 'controler-a80-ns', 'S1037', 'SEVentilation', 'Ventilatoare Baie', 'Modul de comandă care se instalează în doza de comutator și se folosește împreună cu ventilatoarele din seria A80. Permite întârziere la pornire (0 sau 120 secunde) și timp de urmărire (6 sau 15 minute), inclusiv funcționare inversă după stingerea luminii.', 249.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3884-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3884-1.webp', 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/3884-2.webp']::text[], '["Montaj în doza de comutator", "Întârziere la pornire 0 / 120 s", "Timp de urmărire 6 / 15 min"]'::jsonb, '{"Tip produs": "Accesorii", "Control": "Panou integrat"}'::jsonb, 10),
  ('Carcasă aplicată A80i-AP-GEH pentru ventilator A80i', 'carcasa-a80i-ap-geh', 'S1086', 'SEVentilation', 'Ventilatoare Baie', 'Carcasă aplicată cu conexiune din spate, pentru montajul ventilatorului A80i pe perete sau pe tavan.', 344.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4201-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4201-1.webp']::text[], '["Montaj aparent", "Conexiune din spate"]'::jsonb, '{}'::jsonb, 10),
