  ('Carcasă A80i-TBH-GEH pentru gips-carton, conexiune din spate', 'carcasa-a80i-tbh-geh', 'S1088', 'SEVentilation', 'Ventilatoare Baie', 'Carcasă A80i pentru pereți din gips-carton, cu conexiune din spate, potrivită și pentru renovări.', 344.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4203-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4203-1.webp']::text[], '["Pentru gips-carton", "Conexiune din spate"]'::jsonb, '{}'::jsonb, 10),
  ('Carcasă îngropată A80i-UP-GEH, conexiune laterală', 'carcasa-a80i-up-geh', 'S1085', 'SEVentilation', 'Ventilatoare Baie', 'Carcasă îngropată cu conexiune laterală sau din spate, pentru montaj în perete de șaht și tavan, în construcții noi.', 317.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4200-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4200-1.webp']::text[], '["Montaj îngropat", "Conexiune laterală sau din spate"]'::jsonb, '{}'::jsonb, 10),
  ('Dezumidificator vertical DEZ 35 VD', 'dezumidificator-vertical-dez-35-vd', 'X1027', 'NovingAIR', 'Dezumidificatoare', 'Dezumidificator în carcasă metalică aparentă, pentru instalare verticală, destinat locuințelor, apartamentelor și birourilor cu climatizare radiantă. Funcționează ca unitate independentă de aer neutru.', 13741.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4276-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4276-1.webp']::text[], '["Montaj vertical", "Debit aer 320 m³/h", "Capacitate 18 l/24h", "Putere termică 1,10 kW"]'::jsonb, '{"Tip produs": "Dezumidificator", "Tip montaj": "Vertical", "Debit aer": "320 m3/h", "Capacitate dezumidificare": "18.0 l/24h", "Putere termică": "1.10 kW", "Aplicație": "Rezidential / Birouri"}'::jsonb, 10),
  ('Dezumidificator vertical cu răcire DEZ 35 V DC', 'dezumidificator-vertical-dez-35-v-dc', 'X1028', 'NovingAIR', 'Dezumidificatoare', 'Dezumidificator vertical cu răcire și dezumidificare integrate, în carcasă metalică aparentă. Se potrivește locuințelor și birourilor cu sisteme de climatizare radiantă.', 15704.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4278-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4278-1.webp']::text[], '["Montaj vertical", "Răcire și dezumidificare integrate", "Debit aer 320 m³/h", "Capacitate 18 l/24h"]'::jsonb, '{"Tip produs": "Dezumidificator", "Tip montaj": "Vertical", "Debit aer": "320 m3/h", "Capacitate dezumidificare": "18.0 l/24h", "Putere termică": "1.10 kW", "Aplicație": "Rezidential / Birouri"}'::jsonb, 10),
  ('Dezumidificator orizontal pentru tavan fals DEZ+ 30 H D', 'dezumidificator-orizontal-dez-30-h-d', 'X1030', 'NovingAIR', 'Dezumidificatoare', 'Dezumidificator orizontal pentru montaj în tavan fals, cu introducere și evacuare a aerului prin racorduri rectangulare cu flanșă. Se poate comanda de la panouri de perete, vândute ca accesorii. Ideal când vrei să economisești spațiu util.', 13741.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4279-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4279-1.webp']::text[], '["Montaj în tavan fals", "Debit aer 300 m³/h", "Capacitate 18,9 l/24h", "Putere termică 0,62 kW"]'::jsonb, '{"Tip produs": "Dezumificator", "Tip montaj": "Tavan fals", "Debit aer": "300 m3/h", "Capacitate dezumidificare": "18.9 l/24h", "Putere termică": "0.62 kW", "Aplicație": "Rezidential / Birouri"}'::jsonb, 10),
  ('Dezumidificator orizontal pentru tavan fals DEZ+ 50 H D', 'dezumidificator-orizontal-dez-50-h-d', 'X1031', 'NovingAIR', 'Dezumidificatoare', 'Dezumidificator orizontal cu debit mare, pentru montaj în tavan fals, recomandat în locuințe, apartamente și birouri cu climatizare radiantă. Economisește suprafața utilă, iar aerul se introduce și se evacuează prin racorduri rectangulare.', 16030.00, 'https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4281-1.webp', ARRAY['https://sgazuswrfbbkloqfyryt.supabase.co/storage/v1/object/public/media/products/4281-1.webp']::text[], '["Montaj în tavan fals", "Debit aer 500 m³/h", "Capacitate 36,2 l/24h", "Putere termică 1,30 kW"]'::jsonb, '{"Tip produs": "Dezumidificator", "Tip montaj": "Tavan fals", "Debit aer": "500 m3/h", "Capacitate dezumidificare": "36.2 l/24h", "Putere termică": "1.30 kW", "Aplicație": "Rezidential / Birouri"}'::jsonb, 10)
